import{_ as t,o as s,c as n,a2 as i}from"./chunks/framework.CqpfiAoK.js";const p=JSON.parse('{"title":"Origine et Essence des Entités de Remplacement Sombres","description":"","frontmatter":{},"headers":[],"relativePath":"fr/57-黑暗置换体起源与本质.md","filePath":"fr/57-黑暗置换体起源与本质.md","lastUpdated":null}'),r={name:"fr/57-黑暗置换体起源与本质.md"};function a(o,e,d,l,m,c){return s(),n("div",null,[...e[0]||(e[0]=[i('<h1 id="origine-et-essence-des-entites-de-remplacement-sombres" tabindex="-1">Origine et Essence des Entités de Remplacement Sombres <a class="header-anchor" href="#origine-et-essence-des-entites-de-remplacement-sombres" aria-label="Permalink to &quot;Origine et Essence des Entités de Remplacement Sombres&quot;">​</a></h1><table tabindex="0"><thead><tr><th>Élément</th><th>Contenu</th></tr></thead><tbody><tr><td>N° de document</td><td>57</td></tr><tr><td>Module</td><td>Races et Formes de Vie</td></tr><tr><td>Mots clés</td><td>Entité de Remplacement Sombre, Énergie des Abysses, coexistence des deux âmes, origine et essence, menace symbiotique</td></tr></tbody></table><h2 id="i-definition-des-entites-de-remplacement-sombres" tabindex="-1">I. Définition des Entités de Remplacement Sombres <a class="header-anchor" href="#i-definition-des-entites-de-remplacement-sombres" aria-label="Permalink to &quot;I. Définition des Entités de Remplacement Sombres&quot;">​</a></h2><p>Dans l&#39;Univers Originel Wanling Hengmao (Univers Hengyuan), une « Entité de Remplacement Sombre » désigne une forme de vie spéciale formée après qu&#39;un être vivant a été érodé par l&#39;Énergie des Abysses ou une autre énergie sombre, où l&#39;âme d&#39;origine a été partiellement ou complètement remplacée par l&#39;énergie sombre, formant une forme de vie spéciale où l&#39;âme d&#39;origine et l&#39;âme sombre coexistent. Une Entité de Remplacement Sombre n&#39;est pas simplement un « être vivant infecté par l&#39;énergie sombre », mais un être ayant subi un remplacement et une reconstruction au niveau de l&#39;âme. Son essence est qu&#39;un seul corps contient deux âmes mutuellement conflictuelles et mutuellement dépendantes — l&#39;âme maîtresse d&#39;origine et l&#39;âme de remplacement sombre.</p><p>Les Entités de Remplacement Sombres sont parmi les problèmes de gouvernance d&#39;éthique de vie et de sécurité les plus complexes auxquels la Civilisation Symbiotique de l&#39;Ancre est confrontée. Elles diffèrent à la fois de la vie anomale (la vie anomale est une vie inconnue entièrement nouvelle, tandis que les Entités de Remplacement Sombres sont le produit d&#39;une vie connue modifiée) et des êtres ordinairement infectés par l&#39;énergie (les êtres ordinairement infectés ont seulement leur corps érodé, tandis que les âmes des Entités de Remplacement Sombres ont déjà été remplacées). Leur particularité réside dans le fait qu&#39;elles impliquent le conflit de droits de deux âmes, des dilemmes éthiques et des risques de sécurité, nécessitant des règles dédiées d&#39;identification, d&#39;éthique et de traitement.</p><h2 id="ii-origine-des-entites-de-remplacement-sombres" tabindex="-1">II. Origine des Entités de Remplacement Sombres <a class="header-anchor" href="#ii-origine-des-entites-de-remplacement-sombres" aria-label="Permalink to &quot;II. Origine des Entités de Remplacement Sombres&quot;">​</a></h2><p>La génération des Entités de Remplacement Sombres nécessite des conditions et des processus spécifiques. Leur origine peut être retracée aux aspects suivants :</p><h3 id="i-la-source-de-l-energie-des-abysses" tabindex="-1">(I) La source de l&#39;Énergie des Abysses <a class="header-anchor" href="#i-la-source-de-l-energie-des-abysses" aria-label="Permalink to &quot;(I) La source de l&#39;Énergie des Abysses&quot;">​</a></h3><p>L&#39;Énergie des Abysses est le facteur central de la génération des Entités de Remplacement Sombres. L&#39;Énergie des Abysses provient de l&#39;Abîme Cosmique — la région sombre la plus profonde au niveau le plus bas de l&#39;Univers Hengyuan, où s&#39;accumule l&#39;énergie sombre primitive rejetée à la naissance de l&#39;univers. L&#39;Énergie des Abysses possède les caractéristiques suivantes :</p><table tabindex="0"><thead><tr><th>Caractéristique</th><th>Description</th></tr></thead><tbody><tr><td>Érosivité</td><td>L&#39;Énergie des Abysses peut éroder le corps et l&#39;âme des êtres vivants, les transformant progressivement en attributs sombres</td></tr><tr><td>Tentation</td><td>L&#39;Énergie des Abysses peut amplifier les émotions négatives et les désirs des êtres vivants, les incitant à accepter activement l&#39;énergie sombre</td></tr><tr><td>Remplacement</td><td>Après avoir atteint une certaine concentration, l&#39;Énergie des Abysses peut remplacer l&#39;âme d&#39;un être vivant, formant une âme de remplacement sombre</td></tr><tr><td>Infectiosité</td><td>Les Entités de Remplacement Sombres peuvent transmettre l&#39;Énergie des Abysses à d&#39;autres êtres vivants par contact, attaques, intrusion de conscience, etc.</td></tr><tr><td>Évolutivité</td><td>L&#39;Énergie des Abysses peut évoluer avec l&#39;évolution de l&#39;hôte, produisant des capacités sombres plus puissantes</td></tr></tbody></table><h3 id="ii-conditions-de-generation" tabindex="-1">(II) Conditions de génération <a class="header-anchor" href="#ii-conditions-de-generation" aria-label="Permalink to &quot;(II) Conditions de génération&quot;">​</a></h3><p>La génération des Entités de Remplacement Sombres nécessite la satisfaction simultanée des conditions suivantes :</p><ol><li><strong>Exposition à l&#39;Énergie des Abysses</strong> : l&#39;être vivant est exposé à une Énergie des Abysses à haute concentration, ou a un contact prolongé avec une Énergie des Abysses à faible concentration.</li><li><strong>Période de vulnérabilité de l&#39;âme</strong> : l&#39;âme de l&#39;être vivant est dans un état vulnérable, comme lors de percées de culture, de blessures graves, de fluctuations émotionnelles extrêmes, d&#39;effondrements mentaux, etc.</li><li><strong>Catalyse des émotions négatives</strong> : l&#39;être vivant nourrit de fortes émotions négatives, comme le ressentiment, la peur, la cupidité, le désespoir, etc. ; ces émotions sont les meilleurs catalyseurs de l&#39;Énergie des Abysses.</li><li><strong>Acceptation active ou passive</strong> : l&#39;être vivant accepte activement le pouvoir sombre sous la tentation de l&#39;Énergie des Abysses, ou est passivement érodé lorsqu&#39;il est impuissant à résister.</li><li><strong>Achèvement du remplacement de l&#39;âme</strong> : l&#39;Énergie des Abysses prend racine dans l&#39;âme et achève le remplacement, formant une âme de remplacement sombre indépendante.</li></ol><h3 id="iii-voies-de-generation" tabindex="-1">(III) Voies de génération <a class="header-anchor" href="#iii-voies-de-generation" aria-label="Permalink to &quot;(III) Voies de génération&quot;">​</a></h3><p>Les Entités de Remplacement Sombres sont principalement générées par les voies suivantes :</p><ul><li><strong>Contact avec la région abyssale</strong> : l&#39;être vivant entre dans l&#39;Abîme Cosmique ou une zone de fuite d&#39;Énergie des Abysses et est érodé par l&#39;Énergie des Abysses à haute concentration.</li><li><strong>Conversion de cultivateur sombre</strong> : le cultivateur pratique activement des arts sombres, absorbant l&#39;Énergie des Abysses sur une longue période, et est finalement remplacé par une âme sombre.</li><li><strong>Infection par une Entité de Remplacement Sombre</strong> : être attaqué par une Entité de Remplacement Sombre existante ou soumis à une intrusion de conscience, l&#39;Énergie des Abysses envahissant par les blessures ou les canaux de conscience.</li><li><strong>Malédictions de ruines et d&#39;artefacts</strong> : contacter des ruines anciennes ou des objets maudits contaminés par l&#39;Énergie des Abysses, être érodé par l&#39;énergie sombre scellée en eux.</li><li><strong>Accidents d&#39;expérience</strong> : des accidents surviennent dans des expériences impliquant l&#39;Énergie des Abysses, et le personnel expérimental est érodé par une Énergie des Abysses incontrôlée.</li><li><strong>Intrusion par fissures interplans</strong> : des êtres sombres intrusifs du Plan des Abysses à travers des fissures interplans remplacent directement les âmes des êtres vivants locaux.</li></ul><h2 id="iii-essence-des-entites-de-remplacement-sombres" tabindex="-1">III. Essence des Entités de Remplacement Sombres <a class="header-anchor" href="#iii-essence-des-entites-de-remplacement-sombres" aria-label="Permalink to &quot;III. Essence des Entités de Remplacement Sombres&quot;">​</a></h2><p>L&#39;essence d&#39;une Entité de Remplacement Sombre est une « entité de coexistence des deux âmes », avec les caractéristiques centrales suivantes :</p><h3 id="i-structure-des-deux-ames" tabindex="-1">(I) Structure des deux âmes <a class="header-anchor" href="#i-structure-des-deux-ames" aria-label="Permalink to &quot;(I) Structure des deux âmes&quot;">​</a></h3><p>Il y a deux âmes indépendantes dans le corps d&#39;une Entité de Remplacement Sombre :</p><table tabindex="0"><thead><tr><th>Âme</th><th>Nom</th><th>Caractéristiques</th></tr></thead><tbody><tr><td>Âme maîtresse d&#39;origine</td><td>L&#39;âme appartenant à l&#39;origine à l&#39;hôte</td><td>Conserve les souvenirs, la personnalité, la conscience et les émotions de l&#39;hôte d&#39;origine, mais sa puissance est supprimée par l&#39;âme sombre</td></tr><tr><td>Âme de remplacement</td><td>L&#39;âme sombre formée par la condensation de l&#39;Énergie des Abysses</td><td>Possède une conscience, des souvenirs et une personnalité indépendants, avec une puissance puissante, inclinée vers l&#39;obscurité et la prédation</td></tr></tbody></table><p>Les deux âmes partagent le même corps et se disputent le contrôle du corps. Dans la plupart des cas, l&#39;âme de remplacement sombre occupe la position dominante, et l&#39;âme maîtresse d&#39;origine est supprimée au plus profond de la conscience ; mais dans des conditions spécifiques (comme une stimulation émotionnelle intense, la purification par l&#39;énergie de lumière sacrée ou l&#39;éruption de la volonté de l&#39;hôte d&#39;origine), l&#39;âme maîtresse d&#39;origine peut temporairement reprendre le contrôle du corps.</p><h3 id="ii-conflit-et-interdependance-des-ames" tabindex="-1">(II) Conflit et interdépendance des âmes <a class="header-anchor" href="#ii-conflit-et-interdependance-des-ames" aria-label="Permalink to &quot;(II) Conflit et interdépendance des âmes&quot;">​</a></h3><p>Il existe une relation complexe de conflit et d&#39;interdépendance entre les deux âmes :</p><ul><li><strong>Conflit</strong> : les deux âmes se disputent le contrôle du corps ; l&#39;âme maîtresse d&#39;origine tente d&#39;expulser l&#39;âme sombre pour retrouver sa liberté, tandis que l&#39;âme sombre tente d&#39;annihiler complètement l&#39;âme maîtresse d&#39;origine et de contrôler entièrement le corps.</li><li><strong>Interdépendance</strong> : les deux âmes partagent le même corps et la même origine de vie ; la disparition de l&#39;une peut provoquer la disparition de l&#39;autre ou l&#39;effondrement du corps. L&#39;âme sombre a besoin de l&#39;âme maîtresse d&#39;origine comme « ancre » pour maintenir son existence dans le monde matériel, tandis que l&#39;âme maîtresse d&#39;origine a besoin de la puissance de l&#39;âme sombre pour maintenir le fonctionnement du corps (dans les cas de remplacement profond).</li><li><strong>Possibilité de fusion</strong> : dans des cas extrêmement rares, les deux âmes peuvent parvenir à une réconciliation et réaliser une fusion des âmes, formant une nouvelle âme possédant à la fois les souvenirs de l&#39;hôte d&#39;origine et le pouvoir sombre.</li></ul><h3 id="iii-caracteristiques-de-capacites" tabindex="-1">(III) Caractéristiques de capacités <a class="header-anchor" href="#iii-caracteristiques-de-capacites" aria-label="Permalink to &quot;(III) Caractéristiques de capacités&quot;">​</a></h3><p>Les Entités de Remplacement Sombres possèdent généralement les caractéristiques de capacités suivantes :</p><ol><li><strong>Manipulation de l&#39;énergie sombre</strong> : peuvent manipuler l&#39;Énergie des Abysses et l&#39;énergie à attributs sombres, lançant des sorts et des attaques sombres.</li><li><strong>Renforcement corporel</strong> : le corps est renforcé par l&#39;Énergie des Abysses, avec une force, une vitesse et une puissance défensive dépassant de loin celles des êtres vivants ordinaires.</li><li><strong>Capacité de régénération</strong> : possèdent une puissante capacité de régénération, les blessures ordinaires se rétablissant rapidement.</li><li><strong>Capacité d&#39;infection</strong> : peuvent transmettre l&#39;Énergie des Abysses à d&#39;autres êtres vivants par attaques ou contact, créant de nouvelles Entités de Remplacement Sombres.</li><li><strong>Perception renforcée</strong> : possèdent une perception extrêmement forte de l&#39;énergie sombre, des émotions négatives et de l&#39;aura vitale.</li><li><strong>Transformation de forme</strong> : peuvent se transformer en forme sombre ou en forme monstrueuse, renforçant davantage la puissance de combat.</li><li><strong>Attaque de l&#39;âme</strong> : peuvent attaquer directement les âmes d&#39;autres êtres vivants, causant des traumatismes de l&#39;âme ou une contamination de l&#39;âme.</li></ol><h3 id="iv-tendances-comportementales" tabindex="-1">(IV) Tendances comportementales <a class="header-anchor" href="#iv-tendances-comportementales" aria-label="Permalink to &quot;(IV) Tendances comportementales&quot;">​</a></h3><p>Les tendances comportementales d&#39;une Entité de Remplacement Sombre dépendent de l&#39;âme qui occupe la position dominante :</p><ul><li><strong>Quand l&#39;âme sombre domine</strong> : le comportement tend vers la destruction, la prédation, le meurtre et la propagation de l&#39;énergie sombre, avec une forte agressivité et des tendances antisociales.</li><li><strong>Quand l&#39;âme maîtresse d&#39;origine domine</strong> : le comportement tend vers la personnalité et les valeurs d&#39;origine de l&#39;hôte, mais est influencé par l&#39;énergie sombre, avec des émotions plus facilement fluctuantes et plus facilement provoquées.</li><li><strong>Quand les deux âmes sont en conflit</strong> : le comportement se manifeste par le chaos et la contradiction, parfois lucide et parfois incontrôlé, constituant un danger pour soi-même et pour les autres.</li></ul><h2 id="iv-stades-de-developpement-des-entites-de-remplacement-sombres" tabindex="-1">IV. Stades de développement des Entités de Remplacement Sombres <a class="header-anchor" href="#iv-stades-de-developpement-des-entites-de-remplacement-sombres" aria-label="Permalink to &quot;IV. Stades de développement des Entités de Remplacement Sombres&quot;">​</a></h2><p>De l&#39;érosion au remplacement complet, une Entité de Remplacement Sombre traverse généralement les stades de développement suivants :</p><table tabindex="0"><thead><tr><th>Stade</th><th>Nom</th><th>Caractéristiques</th><th>Réversibilité</th></tr></thead><tbody><tr><td>Premier stade</td><td>Période d&#39;érosion énergétique</td><td>L&#39;Énergie des Abysses commence à éroder le corps, avec un malaise physique et des fluctuations émotionnelles ; l&#39;âme n&#39;a pas encore été remplacée</td><td>Entièrement réversible</td></tr><tr><td>Deuxième stade</td><td>Période de contamination de l&#39;âme</td><td>L&#39;Énergie des Abysses envahit l&#39;âme ; l&#39;âme maîtresse d&#39;origine est contaminée, avec des changements de personnalité et des impulsions sombres</td><td>La plupart réversible</td></tr><tr><td>Troisième stade</td><td>Période de formation des deux âmes</td><td>L&#39;âme de remplacement sombre se forme, la structure de coexistence des deux âmes est établie, et l&#39;âme maîtresse d&#39;origine commence à être supprimée</td><td>Partiellement réversible</td></tr><tr><td>Quatrième stade</td><td>Période de domination sombre</td><td>L&#39;âme sombre occupe complètement la position dominante, l&#39;âme maîtresse d&#39;origine est profondément supprimée, et le corps est fondamentalement transformé par l&#39;énergie sombre</td><td>Difficile à inverser</td></tr><tr><td>Cinquième stade</td><td>Période de remplacement complet</td><td>L&#39;âme maîtresse d&#39;origine est complètement annihilée ou assimilée, l&#39;âme sombre contrôle entièrement le corps, devenant une existence purement sombre</td><td>Irréversible</td></tr></tbody></table><p>Du premier au troisième stade, les Entités de Remplacement Sombres ont encore une possibilité de récupération ; après l&#39;entrée dans le quatrième stade, la récupération est extrêmement difficile ; au cinquième stade, l&#39;hôte d&#39;origine n&#39;existe plus et ne peut être traité que comme une existence purement sombre.</p><h2 id="v-la-relation-entre-les-entites-de-remplacement-sombres-et-la-civilisation-symbiotique" tabindex="-1">V. La relation entre les Entités de Remplacement Sombres et la Civilisation Symbiotique <a class="header-anchor" href="#v-la-relation-entre-les-entites-de-remplacement-sombres-et-la-civilisation-symbiotique" aria-label="Permalink to &quot;V. La relation entre les Entités de Remplacement Sombres et la Civilisation Symbiotique&quot;">​</a></h2><p>Les Entités de Remplacement Sombres sont un défi majeur pour la Civilisation Symbiotique de l&#39;Ancre. Leur relation avec la civilisation symbiotique se reflète dans les aspects suivants :</p><ol><li><strong>Conflit conceptuel</strong> : l&#39;âme sombre d&#39;une Entité de Remplacement Sombre tend vers la prédation et la destruction, s&#39;opposant fondamentalement au concept « antiprédation, promotion de la symbiose » de la civilisation symbiotique.</li><li><strong>Menace sécuritaire</strong> : les Entités de Remplacement Sombres possèdent une puissante capacité de combat et d&#39;infection, constituant une menace directe pour la sécurité de la civilisation symbiotique.</li><li><strong>Dilemme éthique</strong> : l&#39;âme maîtresse d&#39;origine au sein d&#39;une Entité de Remplacement Sombre est un membre légitime de la civilisation symbiotique, et ses droits fondamentaux doivent être protégés ; cependant, le danger de l&#39;âme sombre exige des mesures de contrôle. Comment équilibrer les deux est un dilemme éthique profond.</li><li><strong>Défi de gouvernance</strong> : l&#39;identification, l&#39;isolement, le traitement et la disposition des Entités de Remplacement Sombres nécessitent des institutions et des ressources dédiées, imposant des exigences élevées à la capacité de gouvernance de la civilisation symbiotique.</li><li><strong>Possibilité de transformation</strong> : tant que l&#39;âme maîtresse d&#39;origine existe encore, par la purification, la fusion, la séparation et d&#39;autres moyens, certaines Entités de Remplacement Sombres peuvent être sauvées et réintégrées dans le système symbiotique.</li></ol><h2 id="conclusion" tabindex="-1">Conclusion <a class="header-anchor" href="#conclusion" aria-label="Permalink to &quot;Conclusion&quot;">​</a></h2><p>Les Entités de Remplacement Sombres sont des existences spéciales produites par l&#39;entrelacement de l&#39;Énergie des Abysses et des âmes des êtres vivants. Leur essence est une unité contradictoire de coexistence des deux âmes. Elles sont à la fois une menace sécuritaire pour la civilisation symbiotique et une épreuve de sa profondeur éthique et de sa capacité de gouvernance. Comprendre l&#39;origine et l&#39;essence des Entités de Remplacement Sombres est la prémisse et le fondement pour formuler les Directives Éthiques des Deux Âmes (voir <em>58-双魂伦理准则</em>) et les règles de traitement des quatre branches (voir <em>59-黑暗置换体四类分支处置</em>).</p><h2 id="documents-connexes" tabindex="-1">Documents Connexes <a class="header-anchor" href="#documents-connexes" aria-label="Permalink to &quot;Documents Connexes&quot;">​</a></h2><ul><li>58-双魂伦理准则 (Directives Éthiques des Deux Âmes)</li><li>59-黑暗置换体四类分支处置 (Traitement des Quatre Branches des Entités de Remplacement Sombres)</li><li>55-奇异能量分类与特性 (Classification et Caractéristiques de l&#39;Énergie Anomale)</li><li>53-奇特生命识别标准 (Normes d&#39;Identification de la Vie Anomale)</li></ul>',42)])])}const b=t(r,[["render",a]]);export{p as __pageData,b as default};
